const TIRATHGARH_COORDS=[18.9569,81.8514],HEIGHT_COMPARISONS=[{name:"Tirathgarh Falls",heightMeters:91,note:"~91m (300 ft) block waterfall across three main tiers"},{name:"Chitrakote Falls",heightMeters:29,note:"India's widest waterfall, on the Indravati, for comparison"},{name:"Qutub Minar (Delhi)",heightMeters:73,note:"Tallest brick minaret in the world"},{name:"Jog Falls (Karnataka)",heightMeters:253,note:"India's highest un-tiered waterfall"}],TIER_STAGES=[{stage:"1",title:"Upper Tier (~110 ft)",img:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=800",alt:"The uppermost tier of a wide waterfall dropping over a flat rock plain",text:"At the top, the Munga Bahar nallah spreads roughly 200 metres wide across a flat sedimentary rock plain before spilling over the first ledge, an initial drop of about 110 feet."},{stage:"2",title:"Middle Tier (~125 ft)",img:"https://images.unsplash.com/photo-1508739773434-c26b3d09e071?auto=format&fit=crop&q=80&w=800",alt:"A second, taller waterfall tier plunging over rock cuts into a forested gorge",text:"After a short run, the water plunges again — this time about 125 feet — over dramatically cut rock faces into a narrower, forest-lined gorge."},{stage:"3",title:"Lower Distributaries",img:"https://images.unsplash.com/photo-1470770903676-69b98201ea1c?auto=format&fit=crop&q=80&w=800",alt:"Numerous small cascading streams fanning out over rocky steps at the base of a waterfall",text:"Near the base the flow splits again into numerous small streams, each stepping down in 1-2 ft ledges, fanning across the rock in the milky-white cascade Tirathgarh is known for."}],SEASONAL_DATA=[{season:"Monsoon (Jul–Sep)",badgeClass:"badge-monsoon",img:"https://images.unsplash.com/photo-1622401467213-a2fecad55b93?auto=format&fit=crop&q=80&w=600",alt:"A waterfall in heavy, powerful monsoon flow spreading across its full width",title:"Full & Flooded",text:"The Kanger swells to its full width, and every one of Tirathgarh's channels runs at once, producing a broad, roaring wall of water and heavy spray."},{season:"Post-Monsoon to Winter (Oct–Feb)",badgeClass:"badge-winter",img:"https://images.unsplash.com/photo-1601582589907-f92af5ed9db8?auto=format&fit=crop&q=80&w=600",alt:"A calm, clear multi-tiered waterfall with milky-white water flowing over rocks",title:"Clear & Milky-White",text:"Flow settles into distinct, clearly separated tiers running crystal clear to milky-white — considered the best time to view and photograph the full staircase structure."}],GALLERY_IMAGES=[{url:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=800",caption:"Tirathgarh Falls' upper tier spreading across the rock plain",category:"Hero Waterfall"},{url:"https://images.unsplash.com/photo-1508739773434-c26b3d09e071?auto=format&fit=crop&q=80&w=800",caption:"The middle tier plunging into the forested gorge below",category:"Multi-Tier View"},{url:"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&q=80&w=800",caption:"The forested Kanger Valley landscape surrounding the falls",category:"Kanger Valley Landscape"},{url:"https://images.unsplash.com/photo-1587582423116-ec07293f0395?auto=format&fit=crop&q=80&w=800",caption:"Dense sal and bamboo forest typical of Kanger Valley National Park",category:"Forest Ecosystem"}],NEARBY_ATTRACTIONS=[{name:"Kanger Valley National Park",distance:"0-33.5 km (park spans falls to Kolab river)",lat:18.921,lng:81.937,description:"One of India's densest national parks, home to the Bastar hill myna, leopards and mugger crocodiles along the Kanger River."},{name:"Kutumsar Caves",distance:"~27 km",lat:18.95,lng:81.933,description:"Limestone cave system inside the park with stalactite and stalagmite formations and a resident blind cave fish."},{name:"Kailash Caves",distance:"~28 km",lat:18.948,lng:81.928,description:"A second major limestone cave system near Kutumsar, discovered more recently and open to guided visits."},{name:"Chitrakote Falls",distance:"~35 km",lat:19.2065,lng:81.7,description:"India's widest waterfall, a horseshoe-shaped cascade on the Indravati River."}],REFERENCES=[{text:"Wikipedia — Teerathgarh Falls, Bastar District, Chhattisgarh.",link:"https://en.wikipedia.org/wiki/Teerathgarh_Falls"},{text:"Kanger Valley National Park — official park information.",link:"http://www.kangervalley.cg.nic.in/"},{text:"Chhattisgarh Tourism Board — Tirathgarh Waterfall, Jagdalpur.",link:"https://chhattisgarhtourism.co.in/tirathgarh-waterfall-chhattisgarh.html"},{text:"Images: Unsplash contributors (used under the Unsplash License for demonstration purposes).",link:"https://unsplash.com/license"}];"undefined"!=typeof module&&module.exports&&(module.exports={TIRATHGARH_COORDS:TIRATHGARH_COORDS,HEIGHT_COMPARISONS:HEIGHT_COMPARISONS,TIER_STAGES:TIER_STAGES,SEASONAL_DATA:SEASONAL_DATA,GALLERY_IMAGES:GALLERY_IMAGES,NEARBY_ATTRACTIONS:NEARBY_ATTRACTIONS,REFERENCES:REFERENCES});